#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by scripts/ring_mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enp1s0f0np0 | grep -q clsact || tc qdisc add dev enp1s0f0np0 clsact
tc qdisc show dev enp1s0f1np1 | grep -q clsact || tc qdisc add dev enp1s0f1np1 clsact
tc filter show dev enp1s0f1np1 ingress pref 49152 | grep -q flower || tc filter add dev enp1s0f1np1 ingress protocol 0x88b5 pref 49152 handle 49152 flower skip_sw src_mac 4c:bb:47:2e:5f:a2 dst_mac 30:c5:99:bf:e1:48 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 30:c5:99:be:6b:43 pipe action mirred egress redirect dev enp1s0f0np0
tc -s filter show dev enp1s0f1np1 ingress pref 49152 | grep -q in_hw || { echo 'rule pref 49152 on enp1s0f1np1 is not in hardware'; exit 3; }
tc filter show dev enp1s0f0np0 ingress pref 49162 | grep -q flower || tc filter add dev enp1s0f0np0 ingress protocol 0x88b5 pref 49162 handle 49162 flower skip_sw src_mac 30:c5:99:be:6b:43 dst_mac 30:c5:99:bf:e1:47 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:2e:5f:a2 pipe action mirred egress redirect dev enp1s0f1np1
tc -s filter show dev enp1s0f0np0 ingress pref 49162 | grep -q in_hw || { echo 'rule pref 49162 on enp1s0f0np0 is not in hardware'; exit 3; }
ip route show exact 10.100.166.2/32 | grep -q . || ip route add 10.100.166.2/32 via 10.100.160.1 dev enp1s0f0np0 src 10.100.160.2
ip route show exact 10.100.163.1/32 | grep -q . || ip route add 10.100.163.1/32 via 10.100.165.2 dev enP2p1s0f1np1 src 10.100.165.1
for d in roceP2p1s0f1 rocep1s0f0; do systemctl start dsv41-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f1 rocep1s0f0; do systemctl is-active --quiet dsv41-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
